import{c as a,Q as t,j as r,m as o}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"Agent Memory: Characterization and System Implications of Stateful Long-Horizon Workloads","description":"","frontmatter":{"url":"https://arxiv.org/abs/2606.06448","title":"Agent Memory: Characterization and System Implications of Stateful Long-Horizon Workloads","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2606.06448,"authors":["Yasmine Omri","Ziyu Gan","Zachary Broveak","Robin Geens","Zexue He","Alex Pentland","Marian Verhelst","Tsachy Weissman","Thierry Tambe"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2606.06448v1","pdf_path":"pdfs/2606.06448.pdf","published_date":"2026-06-04T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-06-04-agent-memory-characterization-stateful-workloads-2606-06448.md","filePath":"research/papers/2026-06-04-agent-memory-characterization-stateful-workloads-2606-06448.md","lastUpdated":1785909234000}'),s={name:"research/papers/2026-06-04-agent-memory-characterization-stateful-workloads-2606-06448.md"};function i(n,e,l,c,h,d){return t(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="agent-memory-characterization-and-system-implications-of-stateful-long-horizon-workloads" tabindex="-1">Agent Memory: Characterization and System Implications of Stateful Long-Horizon Workloads <a class="header-anchor" href="#agent-memory-characterization-and-system-implications-of-stateful-long-horizon-workloads" aria-label="Permalink to &quot;Agent Memory: Characterization and System Implications of Stateful Long-Horizon Workloads&quot;">​</a></h1><p><strong>Authors</strong>: Yasmine Omri, Ziyu Gan, Zachary Broveak, Robin Geens, Zexue He, Alex Pentland, Marian Verhelst, Tsachy Weissman, Thierry Tambe <strong>Published</strong>: June 04, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2606.06448" target="_blank" rel="noreferrer">https://arxiv.org/abs/2606.06448</a> · <a href="https://arxiv.org/html/2606.06448v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2606.06448 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2606.06448" target="_blank" rel="noreferrer">research/papers/pdfs/2606.06448.pdf</a> (12 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>LLM agents are increasingly deployed on long-horizon tasks requiring sustained reasoning over extended interaction histories. Realizing this at scale requires agents to persistently store, retrieve, and update their own memory across sessions. A rich ecosystem of agent memory systems has emerged spanning flat retrieval, LLM-mediated extraction, consolidating fact stores, and agentic control flows. Yet, their system-level behavior remains uncharacterized. We present the first systems characterization of agent memory. First, we introduce a system-oriented taxonomy classifying agent memory systems along four axes. Second, we build a phase-aware profiling harness attributing cost to construction, retrieval, and generation. Third, we characterize ten representative systems across two benchmark suites, uncovering how design choices shift cost across the write and read paths. Finally, we derive 10 system recommendations covering construction scheduling, capability floors, amortization via query volume, freshness-latency tradeoffs, and fleet-scale management.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>首個 agent memory 的「系統層」特性刻畫（systems characterization），補足過往只談檢索精度的空白。</li><li>提出沿四軸分類的 system-oriented taxonomy；建構 phase-aware profiling harness，將成本歸因到 construction / retrieval / generation 三階段。</li><li>對 10 個代表系統、2 個 benchmark suite 做剖析，揭示設計選擇如何在 write/read path 間移轉成本。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>導出 10 條系統建議：construction scheduling、capability floor、以 query volume 攤銷成本、freshness-latency 取捨、fleet-scale 管理。</li><li>發現設計決策顯著改變 write path（建構/抽取）與 read path（檢索）的成本分佈（質性發現為主，abstract 未列單一量化主數字）。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：僅 10 系統 / 2 benchmark，泛化到更大 fleet 待驗證；建議偏經驗法則，缺正式成本模型。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「phase-aware 成本歸因（construction/retrieval/generation）」直接對應 context-management 的 token budget 與 prompt caching：寫入成本一次、讀取成本多次 → 與「以 query volume 攤銷」一致。</li><li>「capability floor」呼應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的「能力下限」與 model-selection-grid——記憶寫入/抽取需最低模型能力，否則 garbage in。 〔v5.1：所引 workspace 細則已退役 → 見 <code>INDEX.md</code> §v5.1 規則退役對照〕</li><li>⚠️ 落地門檻：本庫無自動化 memory fleet；其 freshness-latency 取捨可作為設計 MEMORY/handoff 快取策略時的概念參考，非可直接套用的工具。</li></ul>',16)])])}const g=a(s,[["render",i]]);export{u as __pageData,g as default};
